/**
 * sitemap.xml generated from the content tree + the fixed legal routes.
 *
 * Phase 4: enumerates the Meridian route set (homepage + all category pages +
 * all service pages) from src/content/meridian.js, so the sitemap and the pages
 * generated by getStaticPaths can never disagree (build-spec §3), plus the two
 * indexable legal routes (A2P brand review must reach the Privacy Policy).
 *
 * Core30 rule 9: zero `.html` URLs — every route is extensionless.
 */
import { SITE_URL } from '../lib/site.js';
import { PRIVACY_ROUTE, TERMS_ROUTE } from '../lib/legal.js';
import { ALL_ROUTES } from '../content/meridian.js';

const abs = (path) => new URL(path, SITE_URL).href;

export async function GET() {
  const urls = [...ALL_ROUTES, PRIVACY_ROUTE, TERMS_ROUTE];

  const body =
    '<?xml version="1.0" encoding="UTF-8"?>\n' +
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
    urls.map((u) => `  <url><loc>${abs(u)}</loc></url>`).join('\n') +
    '\n</urlset>\n';

  return new Response(body, {
    headers: { 'Content-Type': 'application/xml; charset=utf-8' },
  });
}
